import { createGlobalStyle } from "styled-components";

export const viewport = {
  tablet: "47.5rem",
} as const;

export const appStyleText = String.raw`
:root {
  --ink: #071624;
  --ink-soft: #0c2234;
  --paper: #f4f7f8;
  --white: #ffffff;
  --blue: #42c5ef;
  --blue-deep: #0d6d9d;
  --metal: #c6a15b;
  --muted: #667480;
  --line: #ccd6db;
  --max: 77.5rem;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  color: var(--ink);
  background: var(--paper);
  font-family: "DM Sans", Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
}
a { color: inherit; }
.skip-link {
  position: absolute;
  left: 1rem;
  top: -5rem;
  z-index: 100;
  background: var(--white);
  color: var(--ink);
  padding: .75rem 1rem;
}
.skip-link:focus { top: 1rem; }

.site-header {
  position: absolute;
  z-index: 10;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  width: min(calc(100% - 3rem), var(--max));
  min-height: 5.375rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 0.0625rem solid rgba(255,255,255,.18);
  color: var(--white);
}
.brand {
  display: flex;
  align-items: center;
  gap: .8rem;
  font-family: "Manrope", sans-serif;
  font-weight: 800;
  letter-spacing: .1em;
  text-decoration: none;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 2.1875rem;
  height: 2.1875rem;
  border: 0.0625rem solid var(--blue);
  color: var(--blue);
  font-size: .68rem;
  letter-spacing: .04em;
}
nav { display: flex; align-items: center; gap: 2rem; }
nav a { font-size: .86rem; font-weight: 600; text-decoration: none; }
nav a:hover, nav a:focus-visible { color: var(--blue); }
.nav-contact { border: 0.0625rem solid rgba(255,255,255,.4); padding: .55rem 1rem; }

.hero {
  position: relative;
  min-height: 49.375rem;
  overflow: hidden;
  color: var(--white);
  background:
    linear-gradient(90deg, rgba(7,22,36,.99) 0%, rgba(7,22,36,.94) 52%, rgba(7,22,36,.54) 100%),
    url("data:image/webp;base64,...") center right / cover no-repeat,
    linear-gradient(135deg, #071624, #0d4766);
}
.hero::before {
  content: "";
  position: absolute;
  inset: 0 0 0 46%;
  background:
    linear-gradient(90deg, transparent 0 24.6%, rgba(66,197,239,.16) 24.8% 25.2%, transparent 25.4% 49.6%, rgba(66,197,239,.16) 49.8% 50.2%, transparent 50.4% 74.6%, rgba(66,197,239,.16) 74.8% 75.2%, transparent 75.4%),
    linear-gradient(0deg, transparent 0 32.8%, rgba(255,255,255,.12) 33% 33.3%, transparent 33.5% 65.8%, rgba(255,255,255,.12) 66% 66.3%, transparent 66.5%);
  transform: skewX(-8deg) scale(1.1);
  transform-origin: bottom;
}
.hero::after {
  content: "";
  position: absolute;
  width: 31rem;
  height: 31rem;
  right: 5vw;
  bottom: -18rem;
  border: 0.0625rem solid rgba(66,197,239,.22);
  border-radius: 50%;
  box-shadow: 0 0 0 6rem rgba(66,197,239,.025), 0 0 0 12rem rgba(66,197,239,.02);
}
.blueprint { position: absolute; inset: 5.375rem 0 0 46%; opacity: .7; }
.blueprint::before,
.blueprint::after {
  content: "";
  position: absolute;
  background: var(--blue);
  opacity: .35;
}
.blueprint::before { width: 0.0625rem; height: 72%; left: 14%; top: 10%; }
.blueprint::after { height: 0.0625rem; width: 74%; left: 5%; top: 22%; }
.measure {
  position: absolute;
  font-size: .62rem;
  letter-spacing: .18em;
  color: var(--blue);
}
.measure { color: rgba(255,255,255,.48); }
.measure-a { left: 30%; bottom: 12%; }
.measure-b { left: 1%; top: 47%; transform: rotate(-90deg); }
.hero-content {
  position: relative;
  z-index: 2;
  width: min(calc(100% - 3rem), var(--max));
  margin: 0 auto;
  padding-top: 8.75rem;
}
.eyebrow {
  display: flex;
  align-items: center;
  gap: .75rem;
  color: #b8d3df;
  font-size: .8rem;
  text-transform: uppercase;
  letter-spacing: .18em;
  font-weight: 600;
}
.eyebrow span { width: 1.875rem; height: 0.0625rem; background: var(--blue); }
h1, h2, h3 { font-family: "Manrope", sans-serif; line-height: 1.08; }
h1 {
  margin: 1.4rem 0 1.6rem;
  max-width: 50.625rem;
  font-size: clamp(3.4rem, 7.2vw, 6.8rem);
  letter-spacing: -.065em;
  font-weight: 700;
}
.hero-copy { max-width: 40.625rem; color: #cbd7dd; font-size: 1.15rem; line-height: 1.75; }
.hero-actions { display: flex; gap: .8rem; margin-top: 2.4rem; flex-wrap: wrap; }
.button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.8rem;
  min-height: 3.25rem;
  padding: 0 1.3rem;
  border: 0.0625rem solid rgba(255,255,255,.38);
  text-decoration: none;
  font-weight: 700;
  font-size: .9rem;
}
.button-primary { background: var(--blue); border-color: var(--blue); color: var(--ink); }
.button-primary:hover, .button-primary:focus-visible { background: #7edbfa; }
.button-secondary:hover, .button-secondary:focus-visible { border-color: var(--blue); color: var(--blue); }
.availability {
  position: absolute;
  z-index: 2;
  right: max(1.5rem, calc((100vw - var(--max)) / 2));
  bottom: 2.625rem;
  display: flex;
  align-items: flex-start;
  gap: .8rem;
  padding-left: 1rem;
  border-left: 0.0625rem solid rgba(255,255,255,.25);
}
.availability strong, .availability span { display: block; }
.availability strong { font-size: .86rem; }
.availability span { color: #a7bac4; font-size: .76rem; }
.status-dot { flex: 0 0 auto; width: 0.4375rem; height: 0.4375rem; margin-top: .45rem; border-radius: 50%; background: var(--blue); }

section:not(.hero):not(.contact-section) { padding: 8rem max(1.5rem, calc((100vw - var(--max)) / 2)); }
.scroll-reveal-ready [data-scroll-reveal] {
  opacity: 0;
  transition:
    opacity .72s cubic-bezier(.22, 1, .36, 1),
    transform .72s cubic-bezier(.22, 1, .36, 1);
  will-change: opacity, transform;
}
.scroll-reveal-ready [data-scroll-reveal="rise"][data-scroll-direction="down"] { transform: translateY(3rem); }
.scroll-reveal-ready [data-scroll-reveal="rise"][data-scroll-direction="up"] { transform: translateY(-3rem); }
.scroll-reveal-ready [data-scroll-reveal="slide-left"][data-scroll-direction="down"] { transform: translateX(-2.5rem); }
.scroll-reveal-ready [data-scroll-reveal="slide-left"][data-scroll-direction="up"] { transform: translateX(2.5rem); }
.scroll-reveal-ready [data-scroll-reveal="slide-right"][data-scroll-direction="down"] { transform: translateX(2.5rem); }
.scroll-reveal-ready [data-scroll-reveal="slide-right"][data-scroll-direction="up"] { transform: translateX(-2.5rem); }
.scroll-reveal-ready [data-scroll-reveal="scale"][data-scroll-direction="down"] { transform: scale(.96); }
.scroll-reveal-ready [data-scroll-reveal="scale"][data-scroll-direction="up"] { transform: scale(1.04); }
.scroll-reveal-ready [data-scroll-reveal][data-scroll-state="visible"] { opacity: 1; transform: none; }
.section-intro {
  display: grid;
  grid-template-columns: 1fr 3fr;
  gap: 2rem;
  align-items: start;
  margin-bottom: 4.5rem;
}
.section-number { margin: .35rem 0 0; font-size: .72rem; letter-spacing: .19em; font-weight: 700; color: var(--blue-deep); }
.section-intro h2 { margin: 0; font-size: clamp(2.25rem, 4.3vw, 4rem); letter-spacing: -.05em; }
.section-intro > div > p { max-width: 41.875rem; margin: 1.6rem 0 0; color: var(--muted); font-size: 1.08rem; }
.metrics { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 0.0625rem solid var(--line); border-bottom: 0.0625rem solid var(--line); }
.metrics article { min-height: 13.125rem; padding: 2.2rem 1.5rem; border-right: 0.0625rem solid var(--line); }
.metrics article:first-child { padding-left: 0; }
.metrics article:last-child { border-right: 0; }
.metrics strong { display: block; font-family: "Manrope", sans-serif; font-size: clamp(2.7rem, 5vw, 4.6rem); line-height: 1; letter-spacing: -.06em; }
.metrics strong span { color: var(--blue-deep); }
.metrics p { max-width: 13.125rem; margin: 1.2rem 0 0; color: var(--muted); font-size: .9rem; }
.capability-grid { display: grid; grid-template-columns: 1.25fr 1fr 1fr; gap: 0.0625rem; margin-top: 5rem; background: var(--line); border: 0.0625rem solid var(--line); }
.capability { min-height: 18.75rem; padding: 2rem; background: var(--white); }
.capability-featured { background: var(--ink); color: var(--white); }
.capability-index { font-family: "Manrope"; color: var(--blue-deep); font-size: .78rem; }
.capability-featured .capability-index { color: var(--blue); }
.capability h3 { margin: 5.5rem 0 1.2rem; font-size: 1.5rem; }
.capability p { margin: 0; color: var(--muted); }
.capability-featured p { color: #b8c8d0; }

.projects-section { background: var(--ink); color: var(--white); }
.section-intro.light .section-number { color: var(--blue); }
.project-list { display: grid; grid-template-columns: 1.15fr .85fr; gap: 1.25rem; }
.project { min-height: 27.5rem; display: flex; flex-direction: column; padding: 2rem; background: var(--ink-soft); border: 0.0625rem solid rgba(255,255,255,.12); }
.project-primary { background: var(--blue); border-color: var(--blue); color: var(--ink); }
.project-topline { display: flex; justify-content: space-between; gap: 1rem; padding-bottom: 1.2rem; border-bottom: 0.0625rem solid currentColor; opacity: .7; font-size: .72rem; text-transform: uppercase; letter-spacing: .12em; }
.project-body { display: grid; grid-template-columns: 1fr auto; gap: 2rem; align-items: end; flex: 1; }
.project h3 { margin: 0 0 1.2rem; font-size: clamp(2rem, 4vw, 3.5rem); letter-spacing: -.05em; }
.project-body p { max-width: 33.125rem; margin: 0; color: #b7c5cc; }
.project-primary .project-body p { color: #173445; }
.project-value { align-self: center; font-family: "Manrope"; font-size: clamp(2.5rem, 5vw, 5rem); letter-spacing: -.07em; }
.project-scope { display: flex; flex-wrap: wrap; gap: .5rem; padding-top: 1.8rem; }
.project-scope span { padding: .36rem .65rem; border: 0.0625rem solid rgba(255,255,255,.2); font-size: .72rem; }
.project-primary .project-scope span { border-color: rgba(7,22,36,.3); }

.systems-section { background: var(--white); }
.systems-layout { border-top: 0.0625rem solid var(--line); }
.system-story { display: grid; grid-template-columns: 4.375rem 1fr 13.75rem; gap: 2rem; align-items: center; padding: 2.7rem 0; border-bottom: 0.0625rem solid var(--line); }
.system-marker { display: grid; place-items: center; width: 2.625rem; height: 2.625rem; border: 0.0625rem solid var(--line); font-family: "Manrope"; font-weight: 700; color: var(--blue-deep); }
.story-kicker, .mini-label { margin: 0 0 .6rem; color: var(--blue-deep); font-size: .7rem; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; }
.system-story h3 { margin: 0 0 .9rem; font-size: 1.55rem; }
.system-story p:last-child { max-width: 43.75rem; margin: 0; color: var(--muted); }
.system-story > strong { font-family: "Manrope"; font-size: 3rem; text-align: right; letter-spacing: -.05em; }
.system-story > strong small { display: block; color: var(--muted); font-family: "DM Sans"; font-size: .7rem; font-weight: 500; letter-spacing: .08em; text-transform: uppercase; }

.experience-section { background: #e8edef; }
.timeline { border-top: 0.0625rem solid #bac6cb; }
.timeline article { display: grid; grid-template-columns: 1fr 1.5fr 2fr; gap: 2rem; padding: 2.4rem 0; border-bottom: 0.0625rem solid #bac6cb; }
.timeline-date { font-size: .72rem; letter-spacing: .06em; font-weight: 400; color: var(--muted); }
.timeline-role p { margin: 0 0 .45rem; color: var(--muted); font-size: .85rem; }
.timeline-role h3 { margin: 0; font-size: 1.28rem; }
.timeline-copy { margin: 0; color: var(--muted); }
.tools-languages { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; margin-top: 4rem; }
.tools-languages > div { padding-top: 1.3rem; border-top: 0.1875rem solid var(--ink); }
.tools-languages p { margin: .4rem 0 0; }
.tool-list { margin: 1.1rem 0 0; padding: 0; list-style: none; }
.tool-list li { padding: 1rem 0; border-top: 0.0625rem solid #bac6cb; }
.tool-list li:first-child { padding-top: 0; border-top: 0; }
.tool-list strong { display: block; margin-bottom: .2rem; font-family: "Manrope", sans-serif; font-size: .82rem; }
.tool-list span { display: block; color: var(--muted); font-size: .9rem; line-height: 1.55; }

.contact-section { padding: 3rem 2rem; background: var(--blue); color: var(--ink); }
.contact-section .section-number { color: var(--ink); opacity: .65; }
.contact-main { display: grid; grid-template-columns: 1fr 3fr; gap: 2rem; align-items: end; margin: 3rem 0 4rem; }
.contact-main p { max-width: 16.875rem; margin: 0; }
.contact-main > a { font-family: "Manrope"; font-size: clamp(1.7rem, 4.1vw, 3.6rem); font-weight: 700; letter-spacing: -.055em; text-decoration-thickness: 0.0625rem; text-underline-offset: .25em; overflow-wrap: anywhere; }
.contact-meta { display: flex; justify-content: flex-end; gap: 2.5rem; padding-top: 1.5rem; border-top: 0.0625rem solid rgba(7,22,36,.4); font-size: .86rem; font-weight: 600; }
footer { display: flex; justify-content: space-between; gap: 2rem; padding: 1.3rem max(1.5rem, calc((100vw - var(--max)) / 2)); background: var(--ink); color: #8fa3ad; font-size: .67rem; letter-spacing: .13em; text-transform: uppercase; }

@media (max-width: 56.25rem) {
  nav { gap: 1rem; }
  nav a:not(.nav-contact) { display: none; }
  .hero { min-height: 46.25rem; }
  .hero::before, .blueprint { left: 60%; }
  .metrics { grid-template-columns: 1fr 1fr; }
  .metrics article:nth-child(2) { border-right: 0; }
  .metrics article:nth-child(-n+2) { border-bottom: 0.0625rem solid var(--line); }
  .metrics article:nth-child(3) { padding-left: 0; }
  .capability-grid { grid-template-columns: 1fr; }
  .capability { min-height: 15.625rem; }
  .capability h3 { margin-top: 3.2rem; }
  .project-list { grid-template-columns: 1fr; }
  .system-story { grid-template-columns: 3.5rem 1fr; }
  .system-story > strong { grid-column: 2; text-align: left; }
  .timeline article { grid-template-columns: 1fr 2fr; }
  .timeline-copy { grid-column: 2; }
  .contact-main { grid-template-columns: 1fr; }
}

@media (max-width: ${viewport.tablet}) {
  .contact-section { padding: 3rem 1.5rem; }
}

@media (max-width: 38.75rem) {
  .site-header { width: calc(100% - 2rem); }
  .brand { font-size: .85rem; }
  .hero { min-height: 48.75rem; }
  .hero::before, .blueprint { left: 72%; opacity: .45; }
  .hero-content { width: calc(100% - 2rem); padding-top: 8.75rem; }
  h1 { font-size: clamp(3.25rem, 16vw, 4.6rem); }
  .hero-copy { font-size: 1rem; }
  .button { width: 100%; }
  .availability { left: 1rem; right: auto; bottom: 1.75rem; }
  section:not(.hero):not(.contact-section) { padding-top: 5rem; padding-bottom: 5rem; }
  .section-intro { grid-template-columns: 1fr; margin-bottom: 3rem; }
  .section-intro h2 { font-size: 2.4rem; }
  .metrics { grid-template-columns: 1fr; }
  .metrics article { min-height: auto; padding: 1.6rem 0; border-right: 0; border-bottom: 0.0625rem solid var(--line); }
  .metrics article:last-child { border-bottom: 0; }
  .project { min-height: 31.25rem; padding: 1.3rem; }
  .project-body { grid-template-columns: 1fr; align-content: center; }
  .project-value { justify-self: start; }
  .system-story { grid-template-columns: 2.75rem 1fr; gap: 1rem; }
  .system-story > strong { font-size: 2.35rem; }
  .timeline article { grid-template-columns: 1fr; }
  .timeline-copy { grid-column: 1; }
  .tools-languages { grid-template-columns: 1fr; }
  .contact-main { margin-top: 2rem; }
  .contact-meta, footer { flex-direction: column; gap: .7rem; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .scroll-reveal-ready [data-scroll-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
`;

export const AppStyles = createGlobalStyle`${appStyleText}`;
